function drawMenu(t){const w=canvas.width,h=canvas.height;ctx.fillStyle='#000';ctx.fillRect(0,0,w,h);const im=assets['hero.webp'];if(im){ctx.save();ctx.filter='grayscale(1) brightness(.75)';const dw=Math.max(w*.9,h*1.7),dh=dw*.45;ctx.drawImage(im,w*.73-dw*.5+Math.sin(t*.18)*5,h*.49-dh*.5,dw,dh);ctx.restore();}const grad=ctx.createLinearGradient(0,0,w,0);grad.addColorStop(0,'#000' );grad.addColorStop(.35,'#000e');grad.addColorStop(.56,'#0005');grad.addColorStop(1,'#0000');ctx.fillStyle=grad;ctx.fillRect(0,0,w,h);const radial=ctx.createRadialGradient(w*.72,h*.47,0,w*.72,h*.47,w*.55);radial.addColorStop(0,'#ffffff05');radial.addColorStop(1,'#0000');ctx.fillStyle=radial;ctx.fillRect(0,0,w,h);if(Math.sin(t*2.4)> .997){ctx.fillStyle='#c8d4b10b';ctx.fillRect(w*.52,0,w*.48,h);}}
function noise(strength=.045){const w=canvas.width,h=canvas.height;ctx.fillStyle='#c0d9ac';ctx.globalAlpha=strength;for(let i=0;i<70;i++){const y=Math.random()*h;ctx.fillRect(0,y,w,Math.random()*2+1);}ctx.globalAlpha=1;}
function drawPhantom(t){const p=engine.phantom,im=assets['Textures/CustomNight/phantom-bb.png'];if(!im)return;const w=canvas.width,h=canvas.height;ctx.save();if(p.scare>0){ctx.fillStyle='#000';ctx.fillRect(0,0,w,h);const atlas=assets['PhantomBB-atlas.webp'];if(atlas){const f=Math.min(11,Math.floor((1.1-p.scare)/1.1*12));ctx.drawImage(atlas,f%4*936,Math.floor(f/4)*720,936,720,0,0,w,h);}}else if(p.active&&engine.monitor&&p.cam===engine.cam){ctx.globalAlpha=.5;ctx.drawImage(im,0,0,w,h);}ctx.restore();}
function render(t){const w=canvas.width,h=canvas.height;ctx.save();if(engine&&view==='playing'&&engine.disorientation>0){const d=engine.disorientation;ctx.translate(w*.5,h*.5);ctx.rotate(Math.sin(t*1.6)*.009*d);ctx.scale(1+d*.035,1+d*.035);ctx.translate(-w*.5+Math.sin(t*2.9)*7*d,-h*.5+Math.cos(t*2.2)*5*d);ctx.filter='blur('+(d*1.8*canvas.width/innerWidth)+'px)';}if(view==='menu'||view==='intro')drawMenu(t);else if(view==='jump'||view==='preview'){const im=assets[jumpEnemy+'-atlas.webp'];if(im){const f=Math.min(anim[jumpEnemy]-1,Math.floor((t-jumpStart)*22)%anim[jumpEnemy]);ctx.drawImage(im,f%5*800,Math.floor(f/5)*360,800,360,0,0,w,h);}if(Math.random()<.16){ctx.fillStyle='#c6c6ac20';ctx.fillRect(0,0,w,h);}noise(.15);}else if(engine){if(engine.monitor){if(engine.cam===10){ctx.fillStyle='#080808';ctx.fillRect(0,0,w,h);ctx.fillStyle='#fff';ctx.font=Math.round(w*.025)+'px Consolas';ctx.textAlign='center';ctx.fillText('-CAMERA DISABLED-',w*.5,h*.35);ctx.fillText('AUDIO ONLY',w*.5,h*.40);ctx.textAlign='left';}else{drawSceneImage(cameraKey(),.5+Math.sin(t*.1)*.08);}ctx.strokeStyle='#d5dcc657';ctx.lineWidth=1;ctx.strokeRect(w*.025,h*.025,w*.95,h*.95);noise(.018);}else{drawSceneImage('Textures/Office/'+officeKey()+'.webp',.5+pan*.5);drawExpandedOffice();if(engine.power<=0){ctx.fillStyle='#0003';ctx.fillRect(0,0,w,h);}if(engine.lights[0]||engine.lights[1]){ctx.fillStyle='#d8e5aa06';ctx.fillRect(0,0,w,h);}}}else{ctx.fillStyle='#0a0c09';ctx.fillRect(0,0,w,h);}if(staticFlash>0){noise(.4);ctx.fillStyle='#d9e9c3'+Math.floor(Math.min(1,staticFlash)*80).toString(16).padStart(2,'0');ctx.fillRect(0,0,w,h);}ctx.restore();if(engine&&(view==='playing'||view==='demo'))drawPhantom(t);}
function updateHUD(){if(!engine)return;const p=Math.ceil(engine.power);$('night').textContent=(customLevels?'СВОЯ НОЧЬ':'НОЧЬ '+String(engine.night).padStart(2,'0'));$('time').innerHTML=gameTime(engine)+' <small>AM</small>';$('powerNumber').textContent=p+'%';$('powerBar').style.width=(engine.power/engine.maxPower*100)+'%';$('powerBar').style.background=p<20?'#ef6a4e':'#d6e5ad';$('usage').innerHTML=Array.from({length:engine.usage},(_,i)=>'<i class="'+(i>2?'high':'')+'"></i>').join('');['left','right'].forEach((side,i)=>{$(side+'Door').classList.toggle('active',engine.doors[i]);$(side+'Light').classList.toggle('active',engine.lights[i]);$(side+'Door').setAttribute('aria-pressed',String(engine.doors[i]));$(side+'Light').setAttribute('aria-pressed',String(engine.lights[i]));});$('cameraPanel').hidden=!engine.monitor;document.body.classList.toggle('cameras',engine.monitor);document.body.classList.toggle('powerout',engine.power<=0);$('monitor').setAttribute('aria-label',engine.monitor?'Опустить монитор камер':'Поднять монитор камер');$('monitor').disabled=engine.power<=0;$('monitor').querySelector('span').textContent='⌄ ⌄ ⌄';$('location').textContent=engine.power<=0?'ПИТАНИЕ ОТКЛЮЧЕНО':engine.monitor?'ВИДЕОНАБЛЮДЕНИЕ':'ОФИС ОХРАНЫ';$('camClock').textContent=String(Math.floor(engine.elapsed/60)).padStart(2,'0')+':'+String(Math.floor(engine.elapsed%60)).padStart(2,'0')+':'+String(Math.floor(engine.elapsed%1*30)).padStart(2,'0');$('camCode').textContent='CAM '+CAMS[engine.cam][0];$('camName').textContent=CAMS[engine.cam][1];document.querySelectorAll('#mapButtons button').forEach((b,i)=>{b.classList.toggle('selected',i===engine.cam);b.setAttribute('aria-pressed',String(i===engine.cam));});updateExpandedHUD();}
function processEvents(){for(const e of engine.drain()){switch(e.type){case'door':Sound.play('Door',.25);staticFlash=.04;break;case'light':Sound.tone(180,.1,.04,'sawtooth');if(engine.lights[e.data]&&engine.atDoor(e.data))Sound.play('windowscare',.3);break;case'monitor':Sound.play('put down',.45);Sound.camera(e.data);staticFlash=.3;break;case'camera':Sound.play('blip3',.35);staticFlash=.35;break;case'step':if(e.data.name==='Freddy')Sound.play('FreddyLaugh'+(1+Math.floor(Math.random()*3)),.4);Sound.walk(e.data.side,e.data.progress);if(engine.monitor)staticFlash=.18;break;case'retreat':Sound.play('knock2',.35);break;case'run':Sound.run();toast('В западном коридоре слышны быстрые шаги…');break;case'bang':Sound.stopRun();Sound.play('knock2',.6);staticFlash=.5;toast('Удар в левую дверь. Потеряно '+e.data+'% энергии.');break;case'phantomAppear':Sound.play('blip3',.35);toast('ФАНТОМНЫЙ БАЛУН БОЙ — ОПУСТИ МОНИТОР!');break;case'phantomScare':Sound.camera(false);Sound.fan(false);Sound.play('phantom-scream',.8);staticFlash=.15;toast('Фантом! Вентилятор неисправен на 8 секунд, температура +12°C.');break;case'fanReady':toast('Вентилятор исправен. Включи его клавишей F.');break;case'arrival':Sound.metalStep(e.data.side,1,0,true);break;case'musicbox':Sound.music(true);break;case'fan':Sound.fan(e.data);Sound.tone(e.data?180:100,.09,.06,'triangle');break;case'heat':toast(e.data===1?'Офис быстро нагревается. Включи вентилятор.':e.data===2?'Температура 35°C. Скоро начнётся перегрев.':'Выше 40°C: дезориентация. Срочно включи вентилятор.');break;case'restored':Sound.music(false);Sound.fan(engine.fanOn);break;case'blackout':Sound.fan(false);Sound.stopRun();Sound.camera(false);Sound.ambient(false);Sound.play('powerdown',.5);toast('Нет питания. Осталось дождаться утра.');break;case'lost':lose(e.data);break;case'won':win();break;}}}
function active(){return view==='playing'&&!paused&&$('modal').hidden;}
function action(kind,side){if(!active())return;Sound.init();if(kind==='door')engine.toggleDoor(side);if(kind==='light')engine.toggleLight(side);if(kind==='monitor')engine.toggleMonitor();if(kind==='fan')engine.toggleFan();processEvents();updateHUD();}
function setCamera(id){if(!active())return;engine.selectCamera(id);processEvents();updateHUD();}
CAMS.forEach((c,i)=>{const b=document.createElement('button');b.title='CAM '+c[0]+' — '+c[1];b.setAttribute('aria-label',b.title);b.style.left=c[3]/4+'%';b.style.top=c[4]/4+'%';b.style.width=c[5]/4+'%';b.style.height=c[6]/4+'%';b.onclick=()=>setCamera(i);$('mapButtons').appendChild(b);});
async function startNight(n,custom=null){if(custom&&!career.customUnlocked){toast('Своя ночь откроется после прохождения шестой ночи.');return;}if(!Number.isInteger(n)||n<1||n>6)return;if(!loaded){await loading;}if(loadFailed){toast('Часть текстур недоступна. Перезагрузите игру.');return;}await Sound.init();Sound.stopAll();$('modal').hidden=true;$('menu').hidden=true;$('hud').hidden=true;$('transition').hidden=false;document.body.className='playing';view='intro';customLevels=custom;engine=new NightEngine(n,custom,Math.random,career.effects());expandedRoundId=crypto.randomUUID?.()||Date.now()+'-'+Math.random();lastSettlement=null;paused=false;pan=0;targetPan=0;$('transitionCopy').innerHTML='<small>12:00 AM / ПОСТ ОХРАНЫ</small><h2>'+(custom?'СВОЯ НОЧЬ':'НОЧЬ '+n)+'</h2><p>Продержись до 6:00 AM<br>Одна смена — 9 минут</p>';setTimeout(()=>{if(view!=='intro')return;$('transition').hidden=true;$('hud').hidden=false;view='playing';last=performance.now()/1000;Sound.fan(engine.fanOn);updateHUD();if(n===1&&!custom)toast('Фантомный Балун Бой появляется после двух минут. Увидишь его на камере — сразу опусти монитор.');},2000);}
function goMenu(){clearTimeout(previewTimer);if($('demoExit'))$('demoExit').hidden=true;document.documentElement.style.setProperty('--heat','0');$('fanTarget').hidden=true;updateCareerUI();view='menu';paused=false;engine=null;Sound.stopAll();$('menu').hidden=false;$('hud').hidden=true;$('modal').hidden=true;$('transition').hidden=true;document.body.className='';}
function lose(who){settleExpanded();document.documentElement.style.setProperty('--heat','0');$('fanTarget').hidden=true;view='jump';jumpEnemy=who;jumpStart=clock;Sound.stopAll();document.body.className='jumpscare';$('hud').hidden=true;Sound.play('jumpscare',.95);setTimeout(()=>{if(view!=='jump')return;view='over';document.body.className='';showModal('<div class="eyebrow"><span class="red-dot"></span> СИГНАЛ ПОТЕРЯН</div><h2>СМЕНА ОКОНЧЕНА</h2><p>'+({Bonnie:'Бонни вошёл слева. Проверяй левый свет и закрывай дверь, пока он не уйдёт.',Chica:'Чика вошла справа. Свет показывает, стоит ли она у двери.',Freddy:engine.power<=0?'Энергия закончилась. Открывай лишние двери и опускай монитор.':'Фредди добрался до правой двери. Наблюдай за ним на камерах.',Foxy:'Фокси выбежал из бухты. Следи за CAM 1C; при звуке бега закрой левую дверь.'}[who])+'</p><p>Время: '+(engine.hour||12)+' AM · Энергия: '+Math.ceil(engine.power)+'%</p>'+settlementHTML()+'<button class="primary" id="retry">Попробовать снова ↗</button><button class="secondary" id="exit">В меню</button>');$('retry').onclick=()=>startNight(engine.night,customLevels);$('exit').onclick=goMenu;},1700);}
function win(){settleExpanded();document.documentElement.style.setProperty('--heat','0');$('fanTarget').hidden=true;view='won';Sound.stopAll();Sound.play('Clock',.35);$('hud').hidden=true;if(!customLevels){completed=Math.max(completed,engine.night);saved=Math.min(6,engine.night+1);persist();}showModal('<div class="eyebrow">'+(engine.night===6&&!customLevels?'★★★★★★ / ШЕСТЬ СМЕН ПОЗАДИ':'● СМЕНА ЗАВЕРШЕНА')+'</div><h2>6:00 AM</h2><p>'+(engine.night===6&&!customLevels?'Ты пережил все шесть ночей. Своя ночь разблокирована. Своя ночь позволяет испытать себя на сложности 20/20/20/20/20.':'Солнце взошло. Сегодня ты вернёшься домой.')+'</p><p>Осталось энергии: '+Math.ceil(engine.power)+'%</p>'+settlementHTML()+'<button class="secondary" id="earnedShop">Магазин · '+money(career.data.wallet)+'</button><button class="primary" id="next">'+(customLevels?'Ещё раз':engine.night<6?'Следующая ночь ↗':'Своя ночь ↗')+'</button><button class="secondary" id="exit">В меню</button>');if($('earnedShop'))$('earnedShop').onclick=showShop;$('next').onclick=()=>customLevels?startNight(engine.night,customLevels):engine.night<6?startNight(engine.night+1):customMenu();$('exit').onclick=goMenu;}
function showModal(html){$('modalCard').className='modal-card';$('modalCard').innerHTML=html;$('modal').hidden=false;setTimeout(()=>$('modalCard').querySelector('button')?.focus(),0);}
function resume(){paused=false;$('modal').hidden=true;if(view==='playing')Sound.context?.resume();last=performance.now()/1000;}
function pause(){if(view!=='playing')return;paused=true;Sound.context?.suspend();showModal('<div class="eyebrow">СИСТЕМА ПРИОСТАНОВЛЕНА</div><h2>ПЕРЕДЫШКА</h2><p>Ночь ждёт. Энергия, температура и противники остановлены.</p><button class="primary" id="resume">Продолжить смену ↗</button><button class="secondary" id="instructions">Как играть</button><button class="secondary" id="exit">В меню</button>');$('resume').onclick=resume;$('instructions').onclick=help;$('exit').onclick=goMenu;}
function help(){if(view==='playing'){paused=true;Sound.context?.suspend();}showModal('<div class="eyebrow">ИНСТРУКТАЖ / ПОСТ 01</div><h2>ДОЖИВИ ДО УТРА</h2><p>Смена длится 9 минут. У тебя 100% энергии; двери, свет и камеры расходуют её. При отключении питания всё откроется.</p><div class="instructions"><div><b>A / D — двери</b>Бонни приходит слева, Чика и Фредди — справа. Закрой дверь и дождись стука: противник уйдёт.</div><div><b>Q / E — свет</b>Свет показывает гостей у двери. Не оставляй его включённым надолго.</div><div><b>ПРОБЕЛ — камеры</b>Щёлкай по плану здания. Наблюдение сдерживает противников; Фредди замирает при поднятом мониторе.</div><div><b>Фантомный Балун Бой</b>С первой ночи, после двух минут, может появиться на открытой камере. Опусти монитор или переключи камеру за 1,2 секунды. Если задержишься — скример, +12°C и сбой вентилятора на 8 секунд. Фантом не убивает; затем включи вентилятор вручную.</div><div><b>CAM 1C — Фокси</b>Проверяй Пиратскую бухту. Слышишь бег — опусти монитор и закрой левую дверь.</div></div><p>Esc — пауза · M — звук · экранные кнопки работают на телефоне.<br>Скримеры и резкие звуки. F — вентилятор · B — аварийный заряд. Вентилятор также переключается нажатием на него. Он тратит энергию, но без него растёт температура. Без вентилятора температура превышает 40°C примерно за 30 секунд. Выше 40°C обзор дрожит и размывается, время реакции сокращается. Включи вентилятор для охлаждения.<br>Деньги выдаются после смены. Между сменами покупай фигурки и приборы; на стол можно поставить все фигурки одновременно. Точные часы включаются отдельной кнопкой после покупки.<br>Начни с небольшой громкости.</p><p class="credits">Неофициальная игра. Персонажи и оригинальная графика FNAF © Scott Cawthon. <a href="https://github.com/wellsousaaa/Five-Nights-at-Freddys-Web/tree/main/src/media" target="_blank" rel="noopener">Источник текстур и звуков</a>. Код игры создан отдельно.</p><button class="primary" id="closeHelp">Понятно ↗</button>');$('closeHelp').onclick=resume;}
function customMenu(){if(!career.customUnlocked){toast('Своя ночь откроется после прохождения шестой ночи.');return;}if(view==='playing')paused=true;const names=['Бонни','Чика','Фредди','Фокси','Фантомный Балун Бой'];showModal('<div class="eyebrow">КОНФИГУРАЦИЯ / AI LEVEL</div><h2>СВОЯ НОЧЬ</h2><p>0 — выключен. 20 — максимальная активность.</p>'+names.map((n,i)=>'<label class="custom-row">'+n+'<input id="ai'+i+'" aria-label="Уровень '+n+'" type="range" min="0" max="20" value="5"><output id="val'+i+'">5</output></label>').join('')+'<button class="primary" id="customStart">Начать свою ночь ↗</button><button class="secondary" id="closeCustom">Назад</button>');names.forEach((_,i)=>$('ai'+i).oninput=()=>$('val'+i).textContent=$('ai'+i).value);$('customStart').onclick=()=>startNight(6,names.map((_,i)=>Number($('ai'+i).value)));$('closeCustom').onclick=()=>{if(view==='won')goMenu();else resume();};}
$('nose').onclick=()=>{if(active()&&!engine.monitor&&engine.power>0)Sound.honk();};
$('new').onclick=()=>{if(saved>1||completed>0){showModal('<div class="eyebrow">НОВАЯ ИГРА</div><h2>ПЕРВАЯ СМЕНА</h2><p>Смены начнутся с первой ночи. Деньги, покупки и фигурки сохранятся.</p><button class="primary" id="confirmNew">Начать заново ↗</button><button class="secondary" id="cancelNew">Назад</button>');$('confirmNew').onclick=()=>{saved=1;completed=0;persist();startNight(1)};$('cancelNew').onclick=resume;}else startNight(1);};$('continue').onclick=()=>startNight(saved);$('custom').onclick=customMenu;$('help').onclick=help;$('mute').onclick=()=>{Sound.init();Sound.setMute();};$('full').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen?.();else $('game').requestFullscreen?.().catch(()=>toast('Полный экран недоступен в этом окне.'));};$('home').onclick=e=>{e.preventDefault();if(view==='playing')pause();};$('pause').onclick=pause;$('monitor').onclick=e=>{if(e.pointerType==='touch'||e.detail===0||!window.matchMedia('(hover: hover)').matches)action('monitor');};let lastHover=-1;$('monitor').addEventListener('pointerenter',e=>{if(e.pointerType==='mouse'&&clock-lastHover>.35){lastHover=clock;action('monitor');}});['left','right'].forEach((s,i)=>{$(s+'Door').onclick=()=>action('door',i);$(s+'Light').onclick=()=>action('light',i);});
addEventListener('keydown',e=>{if(['INPUT','TEXTAREA'].includes(e.target.tagName))return;const key=e.code;if(['Space','KeyA','KeyD','KeyQ','KeyE','Escape'].includes(key))e.preventDefault();if(e.repeat)return;if(key==='KeyF')action('fan');if(key==='KeyB')useEmergencyCharge();if(key==='KeyM'){$('mute').click();return;}if(key==='Escape'){if(view==='preview'){goMenu();showExtras();return;}if(view==='demo'){goMenu();return;}if(view==='playing'){if(!$('modal').hidden)resume();else pause();}else if(!$('modal').hidden&&view==='menu')resume();return;}if(key==='Space')action('monitor');if(key==='KeyA')action('door',0);if(key==='KeyD')action('door',1);if(key==='KeyQ')action('light',0);if(key==='KeyE')action('light',1);if(key.startsWith('Digit')&&engine?.monitor){const n=Number(key.slice(5));if(n>=1&&n<=9)setCamera(n-1);}});
canvas.addEventListener('pointermove',e=>{targetPan=(e.clientX/innerWidth-.5)*2;});$('hud').addEventListener('pointermove',e=>{targetPan=(e.clientX/innerWidth-.5)*2;});document.addEventListener('visibilitychange',()=>{if(document.hidden&&active())pause();});
let heartbeatAt=0;let hudClock=0;function frame(ms){clock=ms/1000;const dt=Math.min(.1,Math.max(0,clock-last));last=clock;staticFlash=Math.max(0,staticFlash-dt*3);pan+=(targetPan-pan)*Math.min(1,dt*4);if(active()){if(engine.disorientation>0&&clock>=heartbeatAt){Sound.heartbeat(engine.disorientation);heartbeatAt=clock+1.3-engine.disorientation*.45;}engine.tick(dt);processEvents();hudClock+=dt;if(hudClock>.1){updateHUD();hudClock=0;}}if(view==='demo'){engine.tick(dt);processEvents();if(engine.elapsed>=126)resetPhantomDemo();updateHUD();$('night').textContent='ДЕМОНСТРАЦИЯ';}if(engine)placeOfficeTargets();else{$('nose').hidden=true;$('fanTarget').hidden=true;}render(clock);requestAnimationFrame(frame);}requestAnimationFrame(frame);

